mapper.delete:
DELETE FROM agent_acl
WHERE agent_id IN
#{agentId}

mapper.select:
SELECT DISTINCT agent_id
FROM agent_acl
WHERE status = #{status}
  AND (effective_time IS NULL OR effective_time <= #{effectiveAt})
  AND (expire_time IS NULL OR expire_time > #{effectiveAt})
  AND (


            OR (subject_type = #{roleSubjectType} AND subject_id IN

                #{roleId}
            )


            OR (subject_type = #{deptSubjectType} AND subject_id IN

                #{deptId}
            )


  )
